insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b1-02','en-b1-02',null,3,2,'published',1,'{"id":"en-b1-02","baseId":"en-b1-02","revision":1,"level":"B1","levelIndex":3,"order":2,"title":"Present Perfect Continuous: jarayon va davomiylik","objective":"Yaqindan beri davom etayotgan faoliyatni natijadan ajratasiz.","context":"O‘quvchilar loyiha ustida uzoq vaqt ishlagani va nimalarni tugatganini solishtiradi.","prerequisites":["en-b1-01"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour.","Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi.","Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin."],"pattern":"have been working for an hour / have written three pages","examples":["We have been working for an hour.","I have written three pages.","She has been learning English since spring.","He has been running, so he is tired.","I have known her for years.","How long have you been waiting?"],"vocabulary":[{"id":"en-b1-02-v0","term":"progress","meaning":"rivojlanish","ipa":"/ˈprəʊɡres/","collocation":"make progress","example":"Still, we can see real progress: we have collected useful stories, and our map shows where each one happened."},{"id":"en-b1-02-v1","term":"wait","meaning":"kutmoq","ipa":"/weɪt/","collocation":"wait for a friend","example":"How long have you been waiting?"},{"id":"en-b1-02-v2","term":"since","meaning":"… dan beri","ipa":"/sɪns/","collocation":"since spring","example":"She has been learning English since spring."},{"id":"en-b1-02-v3","term":"result","meaning":"natija","ipa":"/rɪˈzʌlt/","collocation":"a clear result","example":"a clear result"}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["have been working for an hour / have written three pages","We have been working for an hour.","I have written three pages."],"timeline":[{"why":"Have been working oldin boshlangan jarayonni hozir bilan bog‘laydi; u davom etayotgan yoki yaqinda tugagan bo‘lishi mumkin.","events":[{"kind":"span","from":100,"to":320,"label":"Bir soat davomida ishlash"}]},{"why":"Have written three pages jarayonning sonli natijasini ko‘rsatadi. Hozir uch sahifa tayyor.","events":[{"kind":"point","x":230,"label":"Uch sahifa yozilgan"},{"kind":"link","from":230,"to":320,"label":"Hozirgi natija"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["O‘quvchilar loyiha ustida uzoq vaqt ishlagani va nimalarni tugatganini solishtiradi.","She has been learning English since spring.","I have known her for years."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"He has been running, so he is tired.","audio":"/english-course/v7.23/en-b1-02-dictation.mp3"},"exercises":[{"id":"en-b1-02-choice","type":"choice","skill":"grammar","prompt":"Jarayonga urg‘u beradigan gapni tanlang.","answers":["I have been writing all morning."],"explanation":"Been writing jarayon.","hint":"have been working for an hour / have written three pages","options":["I have been writing all morning.","I have written three pages.","I wrote last year."]},{"id":"en-b1-02-gap","type":"grammarFill","skill":"grammar","prompt":"She has ___ learning since spring.","answers":["been"],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages"},{"id":"en-b1-02-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We have been working for an hour."],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages","tokens":["We","have","been","working","for","an","hour."]},{"id":"en-b1-02-fix","type":"correction","skill":"grammar","prompt":"I have been knowing her for years.","answers":["I have known her for years."],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages"},{"id":"en-b1-02-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["rivojlanish","kutmoq","… dan beri","natija"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"have been working for an hour / have written three pages","left":["progress","wait","since","result"],"options":["rivojlanish","kutmoq","… dan beri","natija"]}],"reading":{"title":"Present Perfect Continuous: jarayon va davomiylik — vaziyat","text":"Our group has been working on a local history project for two weeks. We have interviewed three neighbours and written six short reports. Ali has been checking dates since Monday, while Lola has been drawing a map. The map is not finished yet, but she has completed the main streets. We have been learning how to ask clearer questions. At first, our interviews were too long and did not have a clear purpose. Now we choose two important questions before each visit. Our teacher has known one of the neighbours for years and helped us arrange a meeting. Today we are tired because we have been walking around the town all morning. Still, we can see real progress: we have collected useful stories, and our map shows where each one happened. We plan to stop for the day and compare the reports tomorrow.","sentences":["Our group has been working on a local history project for two weeks.","We have interviewed three neighbours and written six short reports.","Ali has been checking dates since Monday, while Lola has been drawing a map.","The map is not finished yet, but she has completed the main streets.","We have been learning how to ask clearer questions.","At first, our interviews were too long and did not have a clear purpose.","Now we choose two important questions before each visit.","Our teacher has known one of the neighbours for years and helped us arrange a meeting.","Today we are tired because we have been walking around the town all morning.","Still, we can see real progress: we have collected useful stories, and our map shows where each one happened.","We plan to stop for the day and compare the reports tomorrow."],"questions":[{"id":"en-b1-02-reading0","type":"choice","skill":"reading","prompt":"Six reports qaysi jihatni ta’kidlaydi?","answers":["a completed amount"],"explanation":"Have written six — tugallangan miqdor.","hint":"have been working for an hour / have written three pages","options":["a completed amount","only the duration","a future plan"]},{"id":"en-b1-02-reading1","type":"choice","skill":"reading","prompt":"Nega charchagan?","answers":["they have been walking all morning"],"explanation":"Jarayon ko‘rinadigan hozirgi natijaga bog‘langan.","hint":"have been working for an hour / have written three pages","options":["they have been walking all morning","they have not slept for a month","the map is complete"]},{"id":"en-b1-02-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"have been working for an hour / have written three pages","options":["Our group has been working on a local history project for two weeks.","We have interviewed three neighbours and written six short reports.","Ali has been checking dates since Monday, while Lola has been drawing a map.","The map is not finished yet, but she has completed the main streets.","We have been learning how to ask clearer questions.","At first, our interviews were too long and did not have a clear purpose.","Now we choose two important questions before each visit.","Our teacher has known one of the neighbours for years and helped us arrange a meeting.","Today we are tired because we have been walking around the town all morning.","Still, we can see real progress: we have collected useful stories, and our map shows where each one happened.","We plan to stop for the day and compare the reports tomorrow."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"We have been working for two weeks. We have written six reports and interviewed three neighbours. Lola has been drawing the map, but it is not finished. We are tired because we have been walking all morning.","audio":"/english-course/v7.23/en-b1-02.mp3","synthetic":true,"questions":[{"id":"en-b1-02-listening0","type":"choice","skill":"listening","prompt":"Tayyor hisobot soni?","answers":["six"],"explanation":"Written six reports.","hint":"have been working for an hour / have written three pages","options":["six","two","three"]},{"id":"en-b1-02-listening1","type":"choice","skill":"listening","prompt":"Xarita tugaganmi?","answers":["No"],"explanation":"Not finished.","hint":"have been working for an hour / have written three pages","options":["No","Yes","It was never started"]},{"id":"en-b1-02-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["two weeks","six"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"have been working for an hour / have written three pages","rows":["Ish muddati","Hisobotlar"]},{"id":"en-b1-02-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["He has been running, so he is tired."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"have been working for an hour / have written three pages","audio":"/english-course/v7.23/en-b1-02-dictation.mp3","transcript":"He has been running, so he is tired."}]},"writing":{"task":"Loyihangiz davomiyligi va tugallangan natijalarini alohida ko‘rsatib hisobot yozing.","audience":"Sinfdagi sherigingiz","minWords":90,"maxWords":220,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"We have been preparing a school exhibition for two weeks. I have written four short descriptions, and my friend has taken ten photos. She has been choosing the best pictures since Monday. We have not finished the display yet, but the main title is ready. I have been learning to check dates carefully because one of our first descriptions had a mistake. Our teacher has known the local guide for years, and the guide has helped us find reliable information. Today we are tired because we have been moving tables all morning. We will compare the remaining texts tomorrow before printing them.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["We have been working for an hour.","I have written three pages.","She has been learning English since spring."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"How long …? va How many …? savollariga mos ikki shaklda javob bering.","seconds":75,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Loyihangiz davomiyligi va tugallangan natijalarini alohida ko‘rsatib hisobot yozing.","exit":[[{"id":"en-b1-02-exit0","type":"grammarFill","skill":"grammar","prompt":"We have been ___ for an hour. (work)","answers":["working"],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages"},{"id":"en-b1-02-exit1","type":"grammarFill","skill":"grammar","prompt":"I have ___ three pages. (write)","answers":["written"],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages"},{"id":"en-b1-02-exit2","type":"grammarFill","skill":"grammar","prompt":"How long have you ___ waiting?","answers":["been"],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages"},{"id":"en-b1-02-exit3","type":"choice","skill":"grammar","prompt":"Aniq tugallangan miqdor qaysi?","answers":["I have written six reports."],"explanation":"Six reports natijani o‘lchaydi.","hint":"have been working for an hour / have written three pages","options":["I have written six reports.","I have been writing.","I am writing."]},{"id":"en-b1-02-exit4","type":"choice","skill":"grammar","prompt":"Know uchun odatiy shakl?","answers":["have known"],"explanation":"Holat fe’li.","hint":"have been working for an hour / have written three pages","options":["have known","have been knowing","has knowing"]}],[{"id":"en-b1-02-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I have written three pages."],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages","tokens":["I","have","written","three","pages."]},{"id":"en-b1-02-exit-b1","type":"grammarFill","skill":"grammar","prompt":"I have ___ three pages. (write)","answers":["written"],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages"},{"id":"en-b1-02-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["He has been running, so he is tired."],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages","tokens":["He","has","been","running,","so","he","is","tired."]},{"id":"en-b1-02-exit-b3","type":"choice","skill":"grammar","prompt":"Aniq tugallangan miqdor qaysi?","answers":["I have written six reports."],"explanation":"Six reports natijani o‘lchaydi.","hint":"have been working for an hour / have written three pages","options":["I have written six reports.","I have been writing.","I am writing."]},{"id":"en-b1-02-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["How long have you been waiting?"],"explanation":"Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour. Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi. Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.","hint":"have been working for an hour / have written three pages","tokens":["How","long","have","you","been","waiting?"]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b1-03','en-b1-03',null,3,3,'published',1,'{"id":"en-b1-03","baseId":"en-b1-03","revision":1,"level":"B1","levelIndex":3,"order":3,"title":"Hikoya zamonlari va Past Perfect","objective":"Hikoyadagi avval, davom va asosiy voqeani aniq tartiblaysiz.","context":"Uchrashuvga kelganingizda nima avval bo‘lib o‘tganini tushuntirasiz.","prerequisites":["en-b1-02"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi.","Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left.","Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating."],"pattern":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","examples":["When I arrived, the bus had left.","Lola was waiting outside.","She had checked the timetable.","We called the teacher.","I hadn’t saved the message.","After we had spoken, we chose another route."],"vocabulary":[{"id":"en-b1-03-v0","term":"route","meaning":"yo‘nalish","ipa":"/ruːt/","collocation":"another route","example":"After we had spoken, we chose another route."},{"id":"en-b1-03-v1","term":"timetable","meaning":"jadval","ipa":"/ˈtaɪmteɪbəl/","collocation":"check a timetable","example":"She had checked the timetable."},{"id":"en-b1-03-v2","term":"miss","meaning":"ulgurmay qolmoq","ipa":"/mɪs/","collocation":"miss a bus","example":"He had missed the message too."},{"id":"en-b1-03-v3","term":"earlier","meaning":"oldinroq","ipa":"/ˈɜːliə/","collocation":"leave earlier","example":"leave earlier"}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["When I arrived, the bus had left. / was waiting → arrived → had left earlier","When I arrived, the bus had left.","Lola was waiting outside."],"timeline":[{"why":"Had left voqeasi arriveddan oldin sodir bo‘lgan. Ikkala voqea ham hozirdan oldin.","events":[{"kind":"point","x":95,"label":"Avtobus ketgan"},{"kind":"point","x":210,"label":"Men yetib kelganman"}]},{"why":"Was waiting hikoyadagi o‘tgan paytda davom etayotgan holat. Aniq davomiylik berilmagan.","events":[{"kind":"span","from":75,"to":245,"label":"O‘tgan paytdagi kutish"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Uchrashuvga kelganingizda nima avval bo‘lib o‘tganini tushuntirasiz.","She had checked the timetable.","I hadn’t saved the message."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We called the teacher.","audio":"/english-course/v7.23/en-b1-03-dictation.mp3"},"exercises":[{"id":"en-b1-03-choice","type":"choice","skill":"grammar","prompt":"Avvalgi o‘tmish voqeasini tanlang.","answers":["The bus had left before I arrived."],"explanation":"Had left oldingi nuqta.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["The bus had left before I arrived.","The bus will leave yesterday.","The bus has left yesterday at nine."]},{"id":"en-b1-03-gap","type":"grammarFill","skill":"grammar","prompt":"When I arrived, the bus ___ left.","answers":["had"],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier"},{"id":"en-b1-03-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["When I arrived, the bus had left."],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","tokens":["When","I","arrived,","the","bus","had","left."]},{"id":"en-b1-03-fix","type":"correction","skill":"grammar","prompt":"She had went home.","answers":["She had gone home."],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier"},{"id":"en-b1-03-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["yo‘nalish","jadval","ulgurmay qolmoq","oldinroq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","left":["route","timetable","miss","earlier"],"options":["yo‘nalish","jadval","ulgurmay qolmoq","oldinroq"]},{"id":"en-b1-03-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["route","timetable","miss","earlier"],"options":["another route","check a timetable","miss a bus","leave earlier"],"answers":["another route","check a timetable","miss a bus","leave earlier"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Hikoya zamonlari va Past Perfect — vaziyat","text":"I arrived at the station at nine, but the school bus had already left. Lola was waiting outside the ticket office. She had checked the timetable and knew that a public bus would leave in twenty minutes. I had not saved the teacher’s message, so I did not know the school bus was leaving early. We called the teacher and explained the mistake. While we were talking, another classmate arrived. He had missed the message too. The teacher did not ask us to rush across the city. Instead, she told us to take the public bus and meet the group at the museum entrance. We bought tickets, checked the route, and arrived safely. Later I saved the meeting information in my calendar. The problem taught me to check an arrangement before the day of the trip, not only when I reached the station.","sentences":["I arrived at the station at nine, but the school bus had already left.","Lola was waiting outside the ticket office.","She had checked the timetable and knew that a public bus would leave in twenty minutes.","I had not saved the teacher’s message, so I did not know the school bus was leaving early.","We called the teacher and explained the mistake.","While we were talking, another classmate arrived.","He had missed the message too.","The teacher did not ask us to rush across the city.","Instead, she told us to take the public bus and meet the group at the museum entrance.","We bought tickets, checked the route, and arrived safely.","Later I saved the meeting information in my calendar.","The problem taught me to check an arrangement before the day of the trip, not only when I reached the station."],"questions":[{"id":"en-b1-03-reading0","type":"choice","skill":"reading","prompt":"Avtobus so‘zlovchidan oldin ketganini qaysi shakl ko‘rsatadi?","answers":["had already left"],"explanation":"Had left boshqa o‘tmish nuqtasidan oldin.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["had already left","was waiting","arrived safely"]},{"id":"en-b1-03-reading1","type":"choice","skill":"reading","prompt":"Xulosa nima?","answers":["check arrangements in advance"],"explanation":"Oxirgi gap oldindan tekshirish sabog‘ini beradi.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["check arrangements in advance","always run across the city","never use public transport"]},{"id":"en-b1-03-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["I arrived at the station at nine, but the school bus had already left.","Lola was waiting outside the ticket office.","She had checked the timetable and knew that a public bus would leave in twenty minutes.","I had not saved the teacher’s message, so I did not know the school bus was leaving early.","We called the teacher and explained the mistake.","While we were talking, another classmate arrived.","He had missed the message too.","The teacher did not ask us to rush across the city.","Instead, she told us to take the public bus and meet the group at the museum entrance.","We bought tickets, checked the route, and arrived safely.","Later I saved the meeting information in my calendar.","The problem taught me to check an arrangement before the day of the trip, not only when I reached the station."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"When I arrived at nine, the school bus had left. Lola was waiting outside. She had checked the timetable. A public bus was leaving in twenty minutes. We called our teacher and agreed to meet at the museum.","audio":"/english-course/v7.23/en-b1-03.mp3","synthetic":true,"questions":[{"id":"en-b1-03-listening0","type":"choice","skill":"listening","prompt":"So‘zlovchi nechada kelgan?","answers":["nine"],"explanation":"Arrived at nine.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["nine","eight","ten"]},{"id":"en-b1-03-listening1","type":"choice","skill":"listening","prompt":"Keyingi avtobus qancha vaqtda?","answers":["twenty minutes"],"explanation":"In twenty minutes.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["twenty minutes","an hour","five minutes"]},{"id":"en-b1-03-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["nine","museum"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","rows":["Kelish soati","Yangi uchrashuv joyi"]},{"id":"en-b1-03-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We called the teacher."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","audio":"/english-course/v7.23/en-b1-03-dictation.mp3","transcript":"We called the teacher."}]},"writing":{"task":"Kichik tushunmovchilik haqidagi hikoyani yozing; kamida bir avvalgi voqea va bir fon harakatni ko‘rsating.","audience":"Sinfdagi sherigingiz","minWords":90,"maxWords":220,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I reached the library at four, but my friend had already left. I had written the wrong time in my notebook. Another student was waiting near the door and told me that the meeting had finished at three. I called my friend and explained the mistake. While we were talking, the librarian found the worksheet I needed. My friend had left it for me, so I could still do the task. I thanked them both and checked the next meeting time carefully. Since then, I have put important arrangements in my calendar and read them again the evening before.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["When I arrived, the bus had left.","Lola was waiting outside.","She had checked the timetable."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Nima avval bo‘lganini sherigingiz tushunadigan tartibda hikoya qiling.","seconds":75,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Kichik tushunmovchilik haqidagi hikoyani yozing; kamida bir avvalgi voqea va bir fon harakatni ko‘rsating.","exit":[[{"id":"en-b1-03-exit0","type":"grammarFill","skill":"grammar","prompt":"She had ___ the timetable. (check)","answers":["checked"],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier"},{"id":"en-b1-03-exit1","type":"grammarFill","skill":"grammar","prompt":"We were ___ outside. (wait)","answers":["waiting"],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier"},{"id":"en-b1-03-exit2","type":"grammarFill","skill":"grammar","prompt":"I ___ the teacher yesterday. (call)","answers":["called"],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier"},{"id":"en-b1-03-exit3","type":"choice","skill":"grammar","prompt":"Past Perfect tuzilmasi?","answers":["had + V3"],"explanation":"Had + past participle.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["had + V3","was + base verb","did + V3"]},{"id":"en-b1-03-exit4","type":"choice","skill":"grammar","prompt":"Hikoyadagi hamma gapga had kerakmi?","answers":["No"],"explanation":"Aniq ketma-ketlikda Past Simple yetishi mumkin.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["No","Yes","Always"]}],[{"id":"en-b1-03-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Lola was waiting outside."],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","tokens":["Lola","was","waiting","outside."]},{"id":"en-b1-03-exit-b1","type":"grammarFill","skill":"grammar","prompt":"We were ___ outside. (wait)","answers":["waiting"],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier"},{"id":"en-b1-03-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We called the teacher."],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","tokens":["We","called","the","teacher."]},{"id":"en-b1-03-exit-b3","type":"choice","skill":"grammar","prompt":"Past Perfect tuzilmasi?","answers":["had + V3"],"explanation":"Had + past participle.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["had + V3","was + base verb","did + V3"]},{"id":"en-b1-03-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["After we had spoken, we chose another route."],"explanation":"Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi. Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left. Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","tokens":["After","we","had","spoken,","we","chose","another","route."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b1-04','en-b1-04',null,3,4,'published',1,'{"id":"en-b1-04","baseId":"en-b1-04","revision":1,"level":"B1","levelIndex":3,"order":4,"title":"Used to: avvalgi odat va o‘zgarish","objective":"Hozir o‘zgargan eski odatni tasvirlaysiz.","context":"O‘quvchi bolalikdagi o‘qish odati bilan hozirgisini solishtiradi.","prerequisites":["en-b1-03"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi.","Did you use to …? va didn’t use to … odatiy imtihon shakllari. Did kelganda use asosiy shaklda.","Be used to + ot/-ing esa ko‘nikkan bo‘lishni bildiradi. I used to walk va I am used to walking ikki boshqa ma’no."],"pattern":"used to read / didn’t use to read; am used to reading ≠ used to read","examples":["I used to read only comics.","Now I enjoy longer stories.","She used to live near school.","Did you use to walk there?","I didn’t use to keep notes.","I am used to studying in the library."],"vocabulary":[{"id":"en-b1-04-v0","term":"habit","meaning":"odat","ipa":"/ˈhæbɪt/","collocation":"change a habit","example":"Looking back, I can see that changing one small habit helped more than trying to read a very difficult book in a single night."},{"id":"en-b1-04-v1","term":"longer","meaning":"uzunroq","ipa":"/ˈlɒŋɡə/","collocation":"longer stories","example":"Now I enjoy longer stories."},{"id":"en-b1-04-v2","term":"keep notes","meaning":"qayd yozib bormoq","ipa":"/kiːp nəʊts/","collocation":"keep useful notes","example":"I didn’t use to keep notes."},{"id":"en-b1-04-v3","term":"used to","meaning":"avval odat bo‘lgan","ipa":"/ˈjuːst tə/","collocation":"used to read","example":"I used to read only comics."}],"visuals":[{"kind":"compare","title":"Ma’no va tuzilish","items":["used to read / didn’t use to read; am used to reading ≠ used to read","I used to read only comics.","Now I enjoy longer stories."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["O‘quvchi bolalikdagi o‘qish odati bilan hozirgisini solishtiradi.","She used to live near school.","I didn’t use to keep notes."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Did you use to walk there?","audio":"/english-course/v7.23/en-b1-04-dictation.mp3"},"exercises":[{"id":"en-b1-04-choice","type":"choice","skill":"grammar","prompt":"O‘zgargan eski odat qaysi?","answers":["I used to read only comics."],"explanation":"Used to eski odat.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","options":["I used to read only comics.","I use read comics tomorrow.","I am use to read yesterday."]},{"id":"en-b1-04-gap","type":"grammarFill","skill":"grammar","prompt":"Did you ___ to walk there?","answers":["use"],"explanation":"Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi. Did you use to …? va didn’t use to … odatiy imtihon shakllari. Did kelganda use asosiy shaklda. Be used to + ot/-ing esa ko‘nikkan bo‘lishni bildiradi. I used to walk va I am used to walking ikki boshqa ma’no.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read"},{"id":"en-b1-04-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I used to read only comics."],"explanation":"Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi. Did you use to …? va didn’t use to … odatiy imtihon shakllari. Did kelganda use asosiy shaklda. Be used to + ot/-ing esa ko‘nikkan bo‘lishni bildiradi. I used to walk va I am used to walking ikki boshqa ma’no.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","tokens":["I","used","to","read","only","comics."]},{"id":"en-b1-04-fix","type":"correction","skill":"grammar","prompt":"I am used to study here.","answers":["I am used to studying here."],"explanation":"Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi. Did you use to …? va didn’t use to … odatiy imtihon shakllari. Did kelganda use asosiy shaklda. Be used to + ot/-ing esa ko‘nikkan bo‘lishni bildiradi. I used to walk va I am used to walking ikki boshqa ma’no.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read"},{"id":"en-b1-04-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["odat","uzunroq","qayd yozib bormoq","avval odat bo‘lgan"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","left":["habit","longer","keep notes","used to"],"options":["odat","uzunroq","qayd yozib bormoq","avval odat bo‘lgan"]},{"id":"en-b1-04-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["I used to read only comics."],"tokens":["I","used","to","read","only","comics."],"hint":"used to read / didn’t use to read; am used to reading ≠ used to read","explanation":"Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi."},{"id":"en-b1-04-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Zamonni vaziyatga qarab tanlash: Hozirgi natijaga mos gap?","answers":["We have finished the first shelf."],"explanation":"Natija hozirgi ishga bog‘liq.","hint":"usually help → am helping now → helped yesterday → have finished","options":["We have finished the first shelf.","We have finish yesterday.","We were finish every Friday."],"recap":true,"sourceLesson":"Zamonni vaziyatga qarab tanlash"},{"id":"en-b1-04-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Present Perfect Continuous: jarayon va davomiylik: Jarayonga urg‘u beradigan gapni tanlang.","answers":["I have been writing all morning."],"explanation":"Been writing jarayon.","hint":"have been working for an hour / have written three pages","options":["I have been writing all morning.","I have written three pages.","I wrote last year."],"recap":true,"sourceLesson":"Present Perfect Continuous: jarayon va davomiylik"},{"id":"en-b1-04-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Hikoya zamonlari va Past Perfect: Avvalgi o‘tmish voqeasini tanlang.","answers":["The bus had left before I arrived."],"explanation":"Had left oldingi nuqta.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["The bus had left before I arrived.","The bus will leave yesterday.","The bus has left yesterday at nine."],"recap":true,"sourceLesson":"Hikoya zamonlari va Past Perfect"}],"reading":{"title":"Used to: avvalgi odat va o‘zgarish — vaziyat","text":"When I was younger, I used to read only comics because longer stories seemed difficult. I didn’t use to write new words down. I would forget them and feel frustrated the next day. Last year our teacher showed us how to choose a short book with a topic we liked. I started reading a few pages each evening and keeping simple notes. Now I enjoy longer stories, and I am used to checking unfamiliar words after I have guessed their meaning. My friend used to live near school, but she moved to another part of town. We don’t study together every afternoon now, although we still meet at the weekend. Looking back, I can see that changing one small habit helped more than trying to read a very difficult book in a single night.","sentences":["When I was younger, I used to read only comics because longer stories seemed difficult.","I didn’t use to write new words down.","I would forget them and feel frustrated the next day.","Last year our teacher showed us how to choose a short book with a topic we liked.","I started reading a few pages each evening and keeping simple notes.","Now I enjoy longer stories, and I am used to checking unfamiliar words after I have guessed their meaning.","My friend used to live near school, but she moved to another part of town.","We don’t study together every afternoon now, although we still meet at the weekend.","Looking back, I can see that changing one small habit helped more than trying to read a very difficult book in a single night."],"questions":[{"id":"en-b1-04-reading0","type":"choice","skill":"reading","prompt":"O‘qishdagi o‘zgarishga nima yordam berdi?","answers":["a small regular habit"],"explanation":"Oxirgi xulosa kichik muntazam odatni ta’kidlaydi.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","options":["a small regular habit","one very difficult book overnight","stopping all comics"]},{"id":"en-b1-04-reading1","type":"choice","skill":"reading","prompt":"Am used to nimani bildiradi?","answers":["being accustomed now"],"explanation":"Hozir ko‘nikkan bo‘lish.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","options":["being accustomed now","a finished childhood event","a future decision"]},{"id":"en-b1-04-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","options":["When I was younger, I used to read only comics because longer stories seemed difficult.","I didn’t use to write new words down.","I would forget them and feel frustrated the next day.","Last year our teacher showed us how to choose a short book with a topic we liked.","I started reading a few pages each evening and keeping simple notes.","Now I enjoy longer stories, and I am used to checking unfamiliar words after I have guessed their meaning.","My friend used to live near school, but she moved to another part of town.","We don’t study together every afternoon now, although we still meet at the weekend.","Looking back, I can see that changing one small habit helped more than trying to read a very difficult book in a single night."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I used to read only comics. I didn’t use to keep notes. Now I enjoy longer stories and write down new words. My friend used to live near school, but she moved away. We still meet at weekends.","audio":"/english-course/v7.23/en-b1-04.mp3","synthetic":true,"questions":[{"id":"en-b1-04-listening0","type":"choice","skill":"listening","prompt":"Avval nima qilmagan?","answers":["kept notes"],"explanation":"Didn’t use to keep notes.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","options":["kept notes","read comics","met friends"]},{"id":"en-b1-04-listening1","type":"choice","skill":"listening","prompt":"Do‘sti hozir ham yaqin yashaydimi?","answers":["No"],"explanation":"Moved away o‘zgarishni aytadi.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","options":["No","Yes","The recording does not say"]},{"id":"en-b1-04-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["comics","notes"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","rows":["Eski o‘qish turi","Hozirgi odat"]},{"id":"en-b1-04-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Did you use to walk there?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","audio":"/english-course/v7.23/en-b1-04-dictation.mp3","transcript":"Did you use to walk there?"}]},"writing":{"task":"Eski va hozirgi odatingiz, o‘zgarish sababi va natijasini yozing.","audience":"Sinfdagi sherigingiz","minWords":90,"maxWords":220,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I used to leave my English practice until the weekend. I didn’t use to keep a notebook, so I often forgot useful words. A teacher suggested a smaller daily routine. Now I practise for fifteen minutes each evening and record two phrases I can use. I am used to checking the meaning from context before opening a dictionary. I still make mistakes, but I feel more confident because I can see my progress. This change did not happen in one day. Choosing a realistic task and repeating it helped me more than making a very large plan I could not follow.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I used to read only comics.","Now I enjoy longer stories.","She used to live near school."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Used to va now bilan hayotingizdagi ikki o‘zgarishni sabab bilan tushuntiring.","seconds":75,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Eski va hozirgi odatingiz, o‘zgarish sababi va natijasini yozing.","exit":[[{"id":"en-b1-04-exit0","type":"grammarFill","skill":"grammar","prompt":"I didn’t ___ to keep notes.","answers":["use"],"explanation":"Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi. Did you use to …? va didn’t use to … odatiy imtihon shakllari. Did kelganda use asosiy shaklda. Be used to + ot/-ing esa ko‘nikkan bo‘lishni bildiradi. I used to walk va I am used to walking ikki boshqa ma’no.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read"},{"id":"en-b1-04-exit1","type":"grammarFill","skill":"grammar","prompt":"She used ___ live here.","answers":["to"],"explanation":"Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi. Did you use to …? va didn’t use to … odatiy imtihon shakllari. Did kelganda use asosiy shaklda. Be used to + ot/-ing esa ko‘nikkan bo‘lishni bildiradi. I used to walk va I am used to walking ikki boshqa ma’no.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read"},{"id":"en-b1-04-exit2","type":"grammarFill","skill":"grammar","prompt":"I am used to ___ here. (study)","answers":["studying"],"explanation":"Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi. Did you use to …? va didn’t use to … odatiy imtihon shakllari. Did kelganda use asosiy shaklda. Be used to + ot/-ing esa ko‘nikkan bo‘lishni bildiradi. I used to walk va I am used to walking ikki boshqa ma’no.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read"},{"id":"en-b1-04-exit3","type":"choice","skill":"grammar","prompt":"Used to + qaysi shakl?","answers":["base verb"],"explanation":"Used to live.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","options":["base verb","verb + ing always","V3"]},{"id":"en-b1-04-exit4","type":"choice","skill":"grammar","prompt":"Be used to nimani bildiradi?","answers":["being accustomed"],"explanation":"Ko‘nikkan holat.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","options":["being accustomed","alw