xit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I am used to studying in the library."],"explanation":"Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi. Did you use to …? va didn’t use to … odatiy imtihon shakllari. Did kelganda use asosiy shaklda. Be used to + ot/-ing esa ko‘nikkan bo‘lishni bildiradi. I used to walk va I am used to walking ikki boshqa ma’no.","hint":"used to read / didn’t use to read; am used to reading ≠ used to read","tokens":["I","am","used","to","studying","in","the","library."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b1-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b1-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b1-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b1-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b1-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b1-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b1-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b1-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-b1-04-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Zamonni vaziyatga qarab tanlash: Hozirgi natijaga mos gap?","answers":["We have finished the first shelf."],"explanation":"Natija hozirgi ishga bog‘liq.","hint":"usually help → am helping now → helped yesterday → have finished","options":["We have finished the first shelf.","We have finish yesterday.","We were finish every Friday."],"recap":true,"sourceLesson":"Zamonni vaziyatga qarab tanlash"},{"id":"en-b1-04-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Present Perfect Continuous: jarayon va davomiylik: Jarayonga urg‘u beradigan gapni tanlang.","answers":["I have been writing all morning."],"explanation":"Been writing jarayon.","hint":"have been working for an hour / have written three pages","options":["I have been writing all morning.","I have written three pages.","I wrote last year."],"recap":true,"sourceLesson":"Present Perfect Continuous: jarayon va davomiylik"},{"id":"en-b1-04-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Hikoya zamonlari va Past Perfect: Avvalgi o‘tmish voqeasini tanlang.","answers":["The bus had left before I arrived."],"explanation":"Had left oldingi nuqta.","hint":"When I arrived, the bus had left. / was waiting → arrived → had left earlier","options":["The bus had left before I arrived.","The bus will leave yesterday.","The bus has left yesterday at nine."],"recap":true,"sourceLesson":"Hikoya zamonlari va Past Perfect"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b1-05','en-b1-05',null,3,5,'published',1,'{"id":"en-b1-05","baseId":"en-b1-05","revision":1,"level":"B1","levelIndex":3,"order":5,"title":"Kelajak uchrashuvlari va taxminlar","objective":"Jadval, kelishilgan uchrashuv, niyat va taxminni farqlaysiz.","context":"Ta’lim ko‘rgazmasiga borish rejasini boshqalarga tushuntirasiz.","prerequisites":["en-b1-04"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine.","Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi.","Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas."],"pattern":"train leaves / we’re meeting / going to prepare / will help / when I arrive","examples":["The train leaves at eight.","We are meeting the guide at nine.","I am going to prepare questions.","I think the visit will be useful.","I’ll carry your bag.","I’ll call when I arrive."],"vocabulary":[{"id":"en-b1-05-v0","term":"arrangement","meaning":"kelishilgan reja","ipa":"/əˈreɪndʒmənt/","collocation":"confirm an arrangement","example":"Our teacher reminds us that a clear arrangement needs both a time and a place, not simply a promise to meet sometime in the morning."},{"id":"en-b1-05-v1","term":"prepare","meaning":"tayyorlamoq","ipa":"/prɪˈpeə/","collocation":"prepare questions","example":"I am going to prepare questions."},{"id":"en-b1-05-v2","term":"confirm","meaning":"tasdiqlamoq","ipa":"/kənˈfɜːm/","collocation":"confirm the time","example":"We have already confirmed the tickets, but we will check the timetable again the evening before."},{"id":"en-b1-05-v3","term":"exhibition","meaning":"ko‘rgazma","ipa":"/ˌeksɪˈbɪʃən/","collocation":"visit an exhibition","example":"Our group is visiting an education exhibition next Saturday."}],"visuals":[{"kind":"timetable","title":"Ma’no va tuzilish","items":["train leaves / we’re meeting / going to prepare / will help / when I arrive","The train leaves at eight.","We are meeting the guide at nine."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Ta’lim ko‘rgazmasiga borish rejasini boshqalarga tushuntirasiz.","I am going to prepare questions.","I’ll carry your bag."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"I think the visit will be useful.","audio":"/english-course/v7.23/en-b1-05-dictation.mp3"},"exercises":[{"id":"en-b1-05-choice","type":"choice","skill":"grammar","prompt":"Jadvalni tanlang.","answers":["The train leaves at eight."],"explanation":"Train leaves — jadval.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["The train leaves at eight.","I’ll carry your bag.","I think it will be useful."]},{"id":"en-b1-05-gap","type":"grammarFill","skill":"grammar","prompt":"I’ll call when I ___. (arrive)","answers":["arrive"],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive"},{"id":"en-b1-05-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The train leaves at eight."],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","tokens":["The","train","leaves","at","eight."]},{"id":"en-b1-05-fix","type":"correction","skill":"grammar","prompt":"I will call when I will arrive.","answers":["I will call when I arrive."],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive"},{"id":"en-b1-05-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["kelishilgan reja","tayyorlamoq","tasdiqlamoq","ko‘rgazma"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","left":["arrangement","prepare","confirm","exhibition"],"options":["kelishilgan reja","tayyorlamoq","tasdiqlamoq","ko‘rgazma"]}],"reading":{"title":"Kelajak uchrashuvlari va taxminlar — vaziyat","text":"Our group is visiting an education exhibition next Saturday. The train leaves at eight, and we are meeting our guide at nine. I am going to prepare questions about study habits because that topic matters to our club. Lola thinks the visit will help us choose better practice activities. Ali sees her large folder and offers to carry it. We have already confirmed the tickets, but we will check the timetable again the evening before. The organiser says that the demonstration starts at ten. After it finishes, we will have time to ask questions. I will call my parents when I arrive, and I will send them another message when we leave. Our teacher reminds us that a clear arrangement needs both a time and a place, not simply a promise to meet sometime in the morning.","sentences":["Our group is visiting an education exhibition next Saturday.","The train leaves at eight, and we are meeting our guide at nine.","I am going to prepare questions about study habits because that topic matters to our club.","Lola thinks the visit will help us choose better practice activities.","Ali sees her large folder and offers to carry it.","We have already confirmed the tickets, but we will check the timetable again the evening before.","The organiser says that the demonstration starts at ten.","After it finishes, we will have time to ask questions.","I will call my parents when I arrive, and I will send them another message when we leave.","Our teacher reminds us that a clear arrangement needs both a time and a place, not simply a promise to meet sometime in the morning."],"questions":[{"id":"en-b1-05-reading0","type":"choice","skill":"reading","prompt":"The train leaves qaysi turdagi kelajak?","answers":["a timetable"],"explanation":"Jadvaldagi vaqt.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["a timetable","a sudden offer","an uncertain wish"]},{"id":"en-b1-05-reading1","type":"choice","skill":"reading","prompt":"Qanday reja aniq deyiladi?","answers":["one with a time and place"],"explanation":"Oxirgi gap time va place ni talab qiladi.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["one with a time and place","one without details","only a personal promise"]},{"id":"en-b1-05-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["Our group is visiting an education exhibition next Saturday.","The train leaves at eight, and we are meeting our guide at nine.","I am going to prepare questions about study habits because that topic matters to our club.","Lola thinks the visit will help us choose better practice activities.","Ali sees her large folder and offers to carry it.","We have already confirmed the tickets, but we will check the timetable again the evening before.","The organiser says that the demonstration starts at ten.","After it finishes, we will have time to ask questions.","I will call my parents when I arrive, and I will send them another message when we leave.","Our teacher reminds us that a clear arrangement needs both a time and a place, not simply a promise to meet sometime in the morning."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"The train leaves at eight. We are meeting the guide at nine, and the demonstration starts at ten. I am going to prepare questions. I’ll call home when I arrive.","audio":"/english-course/v7.23/en-b1-05.mp3","synthetic":true,"questions":[{"id":"en-b1-05-listening0","type":"choice","skill":"listening","prompt":"Demonstratsiya qachon?","answers":["ten"],"explanation":"Starts at ten.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["ten","eight","nine"]},{"id":"en-b1-05-listening1","type":"choice","skill":"listening","prompt":"Qachon qo‘ng‘iroq qiladi?","answers":["when he arrives"],"explanation":"When I arrive.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["when he arrives","before buying tickets","next month"]},{"id":"en-b1-05-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["eight","nine"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","rows":["Poyezd","Gid bilan uchrashuv"]},{"id":"en-b1-05-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["I think the visit will be useful."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","audio":"/english-course/v7.23/en-b1-05-dictation.mp3","transcript":"I think the visit will be useful."}]},"writing":{"task":"Safar rejasi uchun jadval, kelishuv, niyat va qayta aloqa vaqtini yozing.","audience":"Sinfdagi sherigingiz","minWords":90,"maxWords":220,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Our group is visiting the exhibition on Saturday. The train leaves at eight, so we are meeting at the station at half past seven. I am going to prepare three questions about learning methods. My friend will bring our tickets, and I’ll carry the shared folder. I think the visit will be useful because we can try different activities. When we arrive, I’ll call our teacher to confirm that everyone is there. After the demonstration finishes, we will ask our questions and write short notes. Please check the meeting place tonight and tell me if you need help finding the station.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["The train leaves at eight.","We are meeting the guide at nine.","I am going to prepare questions."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Uchrashuvni kelishing, reja va taxminni ajratib ayting.","seconds":75,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Safar rejasi uchun jadval, kelishuv, niyat va qayta aloqa vaqtini yozing.","exit":[[{"id":"en-b1-05-exit0","type":"grammarFill","skill":"grammar","prompt":"We are ___ the guide. (meet)","answers":["meeting"],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive"},{"id":"en-b1-05-exit1","type":"grammarFill","skill":"grammar","prompt":"I am going ___ prepare questions.","answers":["to"],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive"},{"id":"en-b1-05-exit2","type":"grammarFill","skill":"grammar","prompt":"When it ___, we will ask questions. (finish)","answers":["finishes"],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive"},{"id":"en-b1-05-exit3","type":"choice","skill":"grammar","prompt":"Shu paytdagi taklif qaysi?","answers":["I’ll carry your bag."],"explanation":"Will taklif qiladi.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["I’ll carry your bag.","The train leaves at eight.","We met yesterday."]},{"id":"en-b1-05-exit4","type":"choice","skill":"grammar","prompt":"When qismida odatiy shakl?","answers":["present"],"explanation":"Kelajak vaqt bog‘lovchisidan keyin present.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["present","will always","Past Perfect always"]}],[{"id":"en-b1-05-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We are meeting the guide at nine."],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","tokens":["We","are","meeting","the","guide","at","nine."]},{"id":"en-b1-05-exit-b1","type":"grammarFill","skill":"grammar","prompt":"I am going ___ prepare questions.","answers":["to"],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive"},{"id":"en-b1-05-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I think the visit will be useful."],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","tokens":["I","think","the","visit","will","be","useful."]},{"id":"en-b1-05-exit-b3","type":"choice","skill":"grammar","prompt":"Shu paytdagi taklif qaysi?","answers":["I’ll carry your bag."],"explanation":"Will taklif qiladi.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["I’ll carry your bag.","The train leaves at eight.","We met yesterday."]},{"id":"en-b1-05-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I’ll call when I arrive."],"explanation":"Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine. Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi. Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","tokens":["I’ll","call","when","I","arrive."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b1-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b1-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b1-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b1-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b1-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b1-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b1-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b1-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b1-06','en-b1-06',null,3,6,'published',1,'{"id":"en-b1-06","baseId":"en-b1-06","revision":1,"level":"B1","levelIndex":3,"order":6,"title":"First va Second Conditional: real va xayoliy","objective":"Haqiqiy ehtimol bilan hozirgi xayoliy vaziyatni ajratasiz.","context":"Kutubxona uchun real budjet va xayoliy katta budjet solishtiriladi.","prerequisites":["en-b1-05"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak.","Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi.","Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi."],"pattern":"If + present, will … / If + past, would …","examples":["If we get funding, we will buy books.","If we had more space, we would build a reading corner.","I would choose a quieter room.","If I were you, I would ask the teacher.","We will start if the plan is approved.","What would you do with a larger budget?"],"vocabulary":[{"id":"en-b1-06-v0","term":"funding","meaning":"mablag‘","ipa":"/ˈfʌndɪŋ/","collocation":"get funding","example":"If we get funding, we will buy books."},{"id":"en-b1-06-v1","term":"budget","meaning":"budjet","ipa":"/ˈbʌdʒɪt/","collocation":"a larger budget","example":"What would you do with a larger budget?"},{"id":"en-b1-06-v2","term":"approve","meaning":"ma’qullamoq","ipa":"/əˈpruːv/","collocation":"approve a plan","example":"We will start if the plan is approved."},{"id":"en-b1-06-v3","term":"corner","meaning":"burchak","ipa":"/ˈkɔːnə/","collocation":"a reading corner","example":"If we had more space, we would build a reading corner."}],"visuals":[{"kind":"cause","title":"Ma’no va tuzilish","items":["If + present, will … / If + past, would …","If we get funding, we will buy books.","If we had more space, we would build a reading corner."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Kutubxona uchun real budjet va xayoliy katta budjet solishtiriladi.","I would choose a quieter room.","We will start if the plan is approved."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"If I were you, I would ask the teacher.","audio":"/english-course/v7.23/en-b1-06-dictation.mp3"},"exercises":[{"id":"en-b1-06-choice","type":"choice","skill":"grammar","prompt":"Real ehtimol qaysi?","answers":["If we get funding, we will start."],"explanation":"Present + will real kelajak sharti.","hint":"If + present, will … / If + past, would …","options":["If we get funding, we will start.","If we had funding, we would start.","We started last year."]},{"id":"en-b1-06-gap","type":"grammarFill","skill":"grammar","prompt":"If we had more space, we ___ build a corner.","answers":["would"],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …"},{"id":"en-b1-06-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["If we get funding, we will buy books."],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …","tokens":["If","we","get","funding,","we","will","buy","books."]},{"id":"en-b1-06-fix","type":"correction","skill":"grammar","prompt":"If I would have money, I would buy books.","answers":["If I had money, I would buy books."],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …"},{"id":"en-b1-06-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["mablag‘","budjet","ma’qullamoq","burchak"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"If + present, will … / If + past, would …","left":["funding","budget","approve","corner"],"options":["mablag‘","budjet","ma’qullamoq","burchak"]},{"id":"en-b1-06-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["funding","budget","approve","corner"],"options":["get funding","a larger budget","approve a plan","a reading corner"],"answers":["get funding","a larger budget","approve a plan","a reading corner"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"First va Second Conditional: real va xayoliy — vaziyat","text":"Our school may give the reading club a small budget. If the plan is approved, we will buy ten new books and repair two chairs. That is a realistic plan for this term. During the meeting, Lola asks what we would do with a much larger budget. If we had more space, we would build a separate reading corner. Ali says he would buy comfortable chairs, while I would choose books in several languages. We know these ideas are not all possible now. The teacher asks us to separate the real request from our future wishes. If I were the organiser, I would explain how each purchase helps students rather than simply choosing the most expensive items. We finally agree to submit the small plan and keep the larger ideas for another discussion.","sentences":["Our school may give the reading club a small budget.","If the plan is approved, we will buy ten new books and repair two chairs.","That is a realistic plan for this term.","During the meeting, Lola asks what we would do with a much larger budget.","If we had more space, we would build a separate reading corner.","Ali says he would buy comfortable chairs, while I would choose books in several languages.","We know these ideas are not all possible now.","The teacher asks us to separate the real request from our future wishes.","If I were the organiser, I would explain how each purchase helps students rather than simply choosing the most expensive items.","We finally agree to submit the small plan and keep the larger ideas for another discussion."],"questions":[{"id":"en-b1-06-reading0","type":"choice","skill":"reading","prompt":"Kichik budjet bilan real ish nima?","answers":["ten books and two repaired chairs"],"explanation":"First Conditionaldagi reja aniq kichik ishlar.","hint":"If + present, will … / If + past, would …","options":["ten books and two repaired chairs","a new building","unlimited computers"]},{"id":"en-b1-06-reading1","type":"choice","skill":"reading","prompt":"Second Conditional bu matnda nima qiladi?","answers":["explores imagined options"],"explanation":"Xayoliy katta budjet muhokamasi.","hint":"If + present, will … / If + past, would …","options":["explores imagined options","reports yesterday’s purchases","guarantees funding"]},{"id":"en-b1-06-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"If + present, will … / If + past, would …","options":["Our school may give the reading club a small budget.","If the plan is approved, we will buy ten new books and repair two chairs.","That is a realistic plan for this term.","During the meeting, Lola asks what we would do with a much larger budget.","If we had more space, we would build a separate reading corner.","Ali says he would buy comfortable chairs, while I would choose books in several languages.","We know these ideas are not all possible now.","The teacher asks us to separate the real request from our future wishes.","If I were the organiser, I would explain how each purchase helps students rather than simply choosing the most expensive items.","We finally agree to submit the small plan and keep the larger ideas for another discussion."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"If our plan is approved, we will buy ten books. If we had a larger budget, we would create a reading corner. For now, we will submit the small plan and keep the bigger ideas for later.","audio":"/english-course/v7.23/en-b1-06.mp3","synthetic":true,"questions":[{"id":"en-b1-06-listening0","type":"choice","skill":"listening","prompt":"Real kitob soni?","answers":["ten"],"explanation":"Ten books.","hint":"If + present, will … / If + past, would …","options":["ten","twenty","one hundred"]},{"id":"en-b1-06-listening1","type":"choice","skill":"listening","prompt":"Katta reja hozir kafolatmi?","answers":["No"],"explanation":"Had/would xayoliy holat.","hint":"If + present, will … / If + past, would …","options":["No","Yes","It is already complete"]},{"id":"en-b1-06-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["ten books","reading corner"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"If + present, will … / If + past, would …","rows":["Real xarid","Xayoliy loyiha"]},{"id":"en-b1-06-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["If I were you, I would ask the teacher."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"If + present, will … / If + past, would …","audio":"/english-course/v7.23/en-b1-06-dictation.mp3","transcript":"If I were you, I would ask the teacher."}]},"writing":{"task":"Real kichik reja va xayoliy kattaroq reja haqida tavsiya yozing.","audience":"Sinfdagi sherigingiz","minWords":90,"maxWords":220,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"If our club receives a small budget, we will buy books that students have requested. We will repair two chairs as well. If we had more money and a larger room, we would create a quiet reading corner with several shelves. However, that is not possible this term. If I were the organiser, I would start with the most useful items and ask students to explain their choices. A realistic plan is easier to approve than a long list without reasons. We will keep the bigger ideas for next year and check whether the first purchases improve our club meetings.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["If we get funding, we will buy books.","If we had more space, we would build a reading corner.","I would choose a quieter room."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Bitta real ehtimol va bitta xayoliy imkoniyatni sabab bilan solishtiring.","seconds":75,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Real kichik reja va xayoliy kattaroq reja haqida tavsiya yozing.","exit":[[{"id":"en-b1-06-exit0","type":"grammarFill","skill":"grammar","prompt":"If I ___ you, I would ask.","answers":["were"],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …"},{"id":"en-b1-06-exit1","type":"grammarFill","skill":"grammar","prompt":"We ___ buy books if it is approved.","answers":["will"],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …"},{"id":"en-b1-06-exit2","type":"grammarFill","skill":"grammar","prompt":"If we ___ more space, we would build it.","answers":["had"],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …"},{"id":"en-b1-06-exit3","type":"choice","skill":"grammar","prompt":"Second Conditionaldagi past har doim o‘tmishmi?","answers":["No"],"explanation":"Xayoliy hozirgi holat bo‘lishi mumkin.","hint":"If + present, will … / If + past, would …","options":["No","Yes","Only with had"]},{"id":"en-b1-06-exit4","type":"choice","skill":"grammar","prompt":"If qismidagi to‘g‘ri shakl?","answers":["If we had money"],"explanation":"Had + would result.","hint":"If + present, will … / If + past, would …","options":["If we had money","If we would have money","If we would had money"]}],[{"id":"en-b1-06-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["If we had more space, we would build a reading corner."],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …","tokens":["If","we","had","more","space,","we","would","build","a","reading","corner."]},{"id":"en-b1-06-exit-b1","type":"grammarFill","skill":"grammar","prompt":"We ___ buy books if it is approved.","answers":["will"],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …"},{"id":"en-b1-06-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["If I were you, I would ask the teacher."],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …","tokens":["If","I","were","you,","I","would","ask","the","teacher."]},{"id":"en-b1-06-exit-b3","type":"choice","skill":"grammar","prompt":"Second Conditionaldagi past har doim o‘tmishmi?","answers":["No"],"explanation":"Xayoliy hozirgi holat bo‘lishi mumkin.","hint":"If + present, will … / If + past, would …","options":["No","Yes","Only with had"]},{"id":"en-b1-06-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["What would you do with a larger budget?"],"explanation":"First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak. Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi. Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.","hint":"If + present, will … / If + past, would …","tokens":["What","would","you","do","with","a","larger","budget?"]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b1-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b1-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b1-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b1-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b1-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b1-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b1-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b1-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b1-07','en-b1-07',null,3,7,'published',1,'{"id":"en-b1-07","baseId":"en-b1-07","revision":1,"level":"B1","levelIndex":3,"order":7,"title":"Passive: ish va natijaga e’tibor","objective":"Present/Past Simple passiveda amalni bajaruvchidan ko‘ra natijani ko‘rsatasiz.","context":"Maktab gazetasi kitob yig‘ish tadbirini yoritadi.","prerequisites":["en-b1-06"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Passive uchun be + V3: Books are collected; The room was cleaned. Be zamonga va egaga mos.","By bajaruvchini aytadi, lekin noma’lum yoki muhim bo‘lmasa tashlab ketiladi. Passive amal bajaruvchini taxmin qilishga ruxsat bermaydi.","Active: students collect books. Passive: books are collected by students. Obyekt yangi gap egasiga aylanganda ma’no saqlansin."],"pattern":"are collected / was cleaned; by + agent when relevant","examples":["Books are collected every Friday.","The room was cleaned yesterday.","New labels are printed in the office.","The poster was designed by Lola.","The tickets were checked at the door.","English is spoken in our club."],"vocabulary":[{"id":"en-b1-07-v0","term":"collect","meaning":"yig‘moq","ipa":"/kəˈlekt/","collocation":"collect books","example":"Books are collected every Friday."},{"id":"en-b1-07-v1","term":"design","meaning":"loyihalamoq","ipa":"/dɪˈzaɪn/","collocation":"design a poster","example":"The poster was designed by Lola."},{"id":"en-b1-07-v2","term":"donate","meaning":"ehson qilmoq","ipa":"/dəʊˈneɪt/","collocation":"donate a book","example":"Last week, sixty books were donated."},{"id":"en-b1-07-v3","term":"notice","meaning":"e’lon","ipa":"/ˈnəʊtɪs/","collocation":"a school notice","example":"The notice does not name every person who carried a box because the report focuses on the result."}],"visuals":[{"kind":"sentence","title":"Ma’no va tuzilish","items":["are collected / was cleaned; by + agent when relevant","Books are collected every Friday.","The room was cleaned yesterday."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Maktab gazetasi kitob yig‘ish tadbirini yoritadi.","New labels are printed in the office.","The tickets were checked at the door."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The poster was designed by Lola.","audio":"/english-course/v7.23/en-b1-07-dictation.mp3"},"exercises":[{"id":"en-b1-07-choice","type":"choice","skill":"grammar","prompt":"Passive tuzilmasini tanlang.","answers":["Books are collected."],"explanation":"Be + V3.","hint":"are collected / was cleaned; by + agent when relevant","options":["Books are collected.","Books collected are students.","Books are collect."]},{"id":"en-b1-07-gap","type":"grammarFill","skill":"grammar","prompt":"The poster was ___ by Lola. (design)","answers":["designed"],"explanation":"Passive uchun be + V3: Books are collected; The room was cleaned. Be zamonga va egaga mos. By bajaruvchini aytadi, lekin noma’lum yoki muhim bo‘lmasa tashlab ketiladi. Passive amal bajaruvchini taxmin qilishga ruxsat bermaydi. Active: students collect books. Passive: books are collected by students. Obyekt yangi gap egasiga aylanganda ma’no saqlansin.","hint":"are collected / was cleaned; by + agent when relevant"},{"id":"en-b1-07-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Books are collected every Friday."],"explanation":"Passive uchun be + V3: Books are collected; The room was cleaned. Be zamonga va egaga mos. By bajaruvchini aytadi, lekin noma’lum yoki muhim bo‘lmasa tashlab ketiladi. Passive amal bajaruvchini taxmin qilishga ruxsat bermaydi. Active: students collect books. Passive: books are collected by students. Obyekt yangi gap egasiga aylanganda ma’no saqlansin.","hint":"are collected / was cleaned; by + agent when relevant","tokens":["Books","are","collected","every","Friday."]},{"id":"en-b1-07-fix","type":"correction","skill":"grammar","prompt":"The tickets were check.","answers":["The tickets were checked."],"explanation":"Passive uchun be + V3: Books are collected; The room was cleaned. Be zamonga va egaga mos. By bajaruvchini aytadi, lekin noma’lum yoki muhim bo‘lmasa tashlab ketiladi. Passive amal bajaruvchini taxmin qilishga ruxsat bermaydi. Active: students collect books. Passive: books are collected by students. Obyekt yangi gap egasiga aylanganda ma’no saqlansin.","hint":"are collected / was cleaned; by + agent when relevant"},{"id":"en-b1-07-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["yig‘moq","loyihalamoq","ehson qilmoq","e’lon"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"are collected / was cleaned; by + agent when relevant","left":["collect","design","donate","notice"],"options":["yig‘moq","loyihalamoq","ehson qilmoq","e’lon"]}],"reading":{"title":"Passive: ish va natijaga e’tibor — vaziyat","text":"Books are collected in our school every Friday. Students bring books they no longer need, and the titles are checked by a teacher. Last week, sixty books were donated. The room was cleaned before the boxes arrived, and new labels were printed in the office. The main poster was designed by Lola, who wanted the instructions to be clear. Damaged books are repaired if possible; books that cannot be used are kept separate. The notice does not name every person who carried a box because the report focuses on the result. However, it thanks the class that organised the event. The new books will be shared with younger readers next month. The teacher says that a useful report should make the process clear and avoid suggesting that a result happened without anyone’s work.","sentences":["Books are collected in our school every Friday.","Students bring books they no longer need, and the titles are checked by a teacher.","Last week, sixty books were donated.","The room was cleaned before the boxes arrived, and new labels were printed in the office.","The main poster was designed by Lola, who wanted the instructions to be clear.","Damaged books are repaired if possible; books that cannot be used are kept separate.","The notice does not name every person who carried a box because the report focuses on the result.","However, it thanks the class that organised the event.","The new books will be shared with younger readers next month.","The teacher says that a useful report should make the process clear and avoid suggesting that a result happened without anyone’s work."],"questions":[{"id":"en-b1-07-reading0","type":"choice","skill":"reading","prompt":"Nega har bir tashuvchi nomi yo‘q?","answers":["the report focuses on the result"],"explanation":"Passive fokusni natijaga ko‘chiradi.","hint":"are collected / was cleaned; by + agent when relevant","options":["the report focuses on the result","nobody carried boxes","the author knows no names"]},{"id":"en-b1-07-reading1","type":"choice","skill":"reading","prompt":"Poster muallifi kim?","answers":["Lola"],"explanation":"By Lola aniq agent.","hint":"are collected / was cleaned; by + agent when relevant","options":["Lola","an unnamed teacher","Ali"]},{"id":"en-b1-07-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"are collected / was cleaned; by + agent when relevant","options":["Books are collected in our school every Friday.","Students bring books they no longer need, and the titles are checked by a teacher.","Last week, sixty books were donated.","The room was cleaned before the boxes arrived, and new labels were printed in the office.","The main poster was designed by Lola, who wanted the instructions to be clear.","Damaged books are repaired if possible; books that cannot be used are kept separate.","The notice does not name every person who carried a box because the report focuses on the result.","However, it thanks the class that organised the event.","The new books will be shared with younger readers next month.","The teacher says that a useful report should make the process clear and avoid suggesting that a result happened without anyone’s work."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Sixty books were donated last week. The room was cleaned before the boxes arrived. New labels were printed in the office. The main poster was designed by Lola. Damaged books are repaired if possible.","audio":"/english-course/v7.23/en-b1-07.mp3","synthetic":true,"questions":[{"id":"en-b1-07-listening0","type":"choice","skill":"listening","prompt":"Kitob soni?","answers":["sixty"],"explanation":"Sixty, sixteen emas.","hint":"are collected / was cleaned; by + agent when relevant","options":["sixty","sixteen","six"]},{"id":"en-b1-07-listening1","type":"choice","skill":"listening","prompt":"Yorliqlar qayerda chop etildi?","answers":["the office"],"explanation":"Printed in the office.","hint":"are collected / was cleaned; by + agent when relevant","options":["the office","the station","the garden"]},{"id":"en-b1-07-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["sixty","Lola"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"are collected / was cleaned; by + agent when relevant","rows":["Kitoblar","Poster muallifi"]},{"id":"en-b1-07-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The poster was designed by Lola."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"are collected / was cleaned; by + agent when relevant","audio":"/english-course/v7.23/en-b1-07-dictation.mp3","transcript":"The poster was designed by Lola."}]},"writing":{"task":"Bir maktab tadbiri haqida jarayon va natija fokusidagi qisqa yangilik yozing.","audience":"Sinfdagi sherigingiz","minWords":90,"maxWords":220,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"A book collection event was organised at our school last Friday. Students brought books that younger readers could use. The titles were checked by two teachers, and damaged pages were repaired where possible. Sixty books were collected in total. The room was cleaned before the boxes arrived, and labels were printed in the office. A poster designed by our class explained how to donate a book. The report focuses on what was done, but the organisers also thanked the volunteers. Next month the books will be shared with the junior classes during their reading lessons.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["Books are collected every Friday.","The room was cleaned yesterday.","New labels are printed in the office."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Bir tadbirni active va passive shaklda ikki xil fokus bilan sharhlang.","seconds":75,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Bir maktab tadbiri haqida jarayon va natija fokusidagi qisqa yangilik yozing.","exit":[[{"id":"en-b1-07-exit0","type":"grammarFill","skill":"grammar","prompt":"The room ___ cleaned yesterday.","answers":["was"],"explanation":"Passive uchun be + V3: Books are collected; The room was cleaned. Be zamonga va egaga mos. By bajaruvchini aytadi, lekin noma’lum yoki muhim bo‘lmasa tashlab ketiladi. Passive amal bajaruvchini taxmin qilishga ruxsat bermaydi. Active: students collect books. Passive: books are collected by students. Obyekt yangi gap egasiga aylanganda ma’no saqlansin.","hint":"are collected / was cleaned; by + agent when relevant"},{"id":"en-b1-07-exit1","type":"grammarFill","skill":"grammar","prompt":"Books ___ collected every Friday.","answers":["are"],"explanation":"Passive uchun be + V3: Books are collected; The room was cleaned. Be zamonga va egaga mos. By bajaruvchini aytadi, lekin noma’lum yoki muhim bo‘lmasa tashlab ketiladi. Passive amal bajaruvchini taxmin qilishga ruxsat bermaydi. Active: students collect books. Passive: books are collected by students. Obyekt yangi gap egasiga aylanganda ma’no saqlansin.","hint":"are collected / was cleaned; by + agent when relevant"},{"id":"en-b1-07-exit2","type":"grammarFill","skill":"grammar","prompt":"The tickets were ___. (check)","answers":["checked"],"explanation":"Passive uchun be + V3: Books are collected; The room was cleaned. Be zamonga va egaga mos. By bajaruvchini aytadi, lekin noma’lum yoki muhim bo‘lmasa tashlab ketiladi. Passive amal bajaruvchini taxmin qilishga ruxsat bermaydi. Active: students collect books. Passive: books are collected by students. Obyekt yangi gap egasiga aylanganda ma’no saqlansin.","hint":"are collected / was cleaned; by + agent when relevant"},{"id":"en-b1-07-exit3","type":"choice","skill":"grammar","prompt":"By nimani kiritadi?","answers":["the agent"],"explanation":"Bajaruvchini.","hint":"are collected / was cleaned; by + agent when relevant","options":["the agent","only the date","the new object"]},